const units = text => Array.from(text, c => c.codePointAt(0));
const bytes = values => new Uint8Array(values);
let count = 0;
for (const [encoding,input,expected] of [
  ['shift_jis',[0x41,0x82,0xa0,0xa1,0x93,0xfa], [65,12354,65377,26085]],
  ['euc-jp',[0x41,0xa4,0xa2,0x8f,0xa2,0xaf,0x8e,0xa1],[65,12354,728,65377]]
]) {
  for (let i=0; i<=input.length; i++) for(let j=i; j<=input.length; j++) {
    const d = new TextDecoder(encoding);
    let out = d.decode(bytes(input.slice(0,i)), {stream:true});
    out += d.decode(bytes(input.slice(i,j)), {stream:true});
    out += d.decode(bytes(input.slice(j)), {stream:true});
    out += d.decode();
    if (JSON.stringify(units(out)) !== JSON.stringify(expected)) throw Error('partition '+i+':'+j);
    count++;
  }
}
console.log(count);

const units = text => Array.from(text, c => c.codePointAt(0));
const bytes = values => new Uint8Array(values);
for (const [encoding,prefix] of [['shift_jis',[0x82]],['euc-jp',[0x8e]],['euc-jp',[0x8f,0xa2]]]) {
  for (const flush of [false,true]) {
    const d = new TextDecoder(encoding, {fatal:true});
    d.decode(bytes(prefix), {stream:true});
    try { d.decode(bytes(flush ? [] : [0x22]), {stream:!flush}); console.log('unexpected-success'); }
    catch(error) { console.log(error.name, d.decode(bytes([0x4f,0x4b]))); }
  }
}

const units = text => Array.from(text, c => c.codePointAt(0));
const bytes = values => new Uint8Array(values);
for (const [encoding,input] of [['shift_jis',[0x93,0xfa,0x96,0x7b,0x8c,0xea]],['euc-jp',[0xc6,0xfc,0xcb,0xdc,0xb8,0xec]]]) {
  const all = bytes([0xff,0xff,...input,0xff,0xff]);
  const d = new TextDecoder(encoding);
  console.log(JSON.stringify(units(d.decode(new DataView(all.buffer,2,6)))));
  console.log(JSON.stringify(units(d.decode(new Uint16Array(all.buffer,2,3)))));
}

const units = text => Array.from(text, c => c.codePointAt(0));
const bytes = values => new Uint8Array(values);
for (const [encoding,prefix,suffix] of [['shift_jis',[0x82],[0xa0]],['euc-jp',[0x8f,0xa2],[0xb7]]]) {
  const d = new TextDecoder(encoding), buffer = bytes(prefix);
  d.decode(buffer, {stream:true});
  buffer.fill(0);
  console.log(JSON.stringify(units(d.decode(bytes(suffix)))));
}

const units = text => Array.from(text, c => c.codePointAt(0));
const bytes = values => new Uint8Array(values);
for (const [encoding,prefix,suffix,outer] of [['shift_jis',[0x82],[0xa0],[0x82,0xa4]],['euc-jp',[0xa4],[0xa2],[0xa4,0xa6]]]) {
  const d = new TextDecoder(encoding); let nested;
  d.decode(bytes(prefix), {stream:true});
  const result = d.decode(bytes(outer), {get stream() {
    nested = d.decode(bytes(suffix), {stream:true}); return false;
  }});
  console.log(JSON.stringify(units(nested)), JSON.stringify(units(result)));
}

